import React, { useState, useEffect } from "react";
import "./clippreview.css";

function ClipPreview({ videoUrl, videoThumbnail }) {
  const [clipPaths, setClipPaths] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchClips = async () => {
      setIsLoading(true);
      setError(null);
      try {
        const response = await fetch("/your-django-endpoint/", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ videoURL: videoUrl }), // Pass the video URL
        });

        if (!response.ok) {
          throw new Error(`Failed to fetch clips: ${response.statusText}`);
        }

        const data = await response.json();
        if (data.clips) {
          setClipPaths(data.clips); // Set the clip paths
        } else {
          throw new Error("No clips found in the response.");
        }
      } catch (err) {
        setError(err.message);
      } finally {
        setIsLoading(false);
      }
    };

    if (videoUrl) {
      fetchClips();
    }
  }, [videoUrl]);

  return (
    <div className="clipping-app">
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          <a href="#clipper">Clipper</a>
          <a href="#seo">SEO</a>
          <a href="#thumbnail">Thumbnail</a>
          <a href="#pricing">Pricing</a>
          <button className="sign-in">Sign in</button>
          <button className="sign-up">Sign up</button>
        </nav>
      </header>

      <main className="main-content">
        <section className="clipper-section">
          <button className="clipper-btn">Clipper</button>

          <div className="long-video">
            <h2>Your long video</h2>
            <div className="video-preview">
              {videoUrl ? (
                <video src={videoUrl} controls className="preview-video" />
              ) : (
                <img
                  src={videoThumbnail || "https://via.placeholder.com/300x200"}
                  alt="Video Thumbnail"
                  className="preview-image"
                />
              )}
            </div>
          </div>

          <div className="viral-clips">
            <h3>Your Viral Clips</h3>
            <div className="clip-thumbnails">
              {isLoading ? (
                <p>Loading clips...</p>
              ) : error ? (
                <p className="error-message">{error}</p>
              ) : clipPaths && clipPaths.length > 0 ? (
                clipPaths.map((clip, index) => (
                  <video
                    key={index}
                    src={clip.clip_path} // Use the absolute path from the backend
                    controls
                    className="clip-thumbnail"
                  />
                ))
              ) : (
                <p>No clips available to display.</p>
              )}
            </div>
          </div>
        </section>
      </main>
    </div>
  );
}

export default ClipPreview;
